import {KEY,seed,escape as e,validWork,validImage,filterWorks,MIN_PRICE,formatPrice as currency,refreshDemoPrices,refreshDemoPresentation,canExhibit} from './data.js';
import {galleryMarkup,mountGallery} from './gallery.js';
import {artworkMarkup,mountArtwork} from './artwork.js';
import {createWorld} from './world.js';
import {frames,frameFor} from './frames.js';
const $=(s,r=document)=>r.querySelector(s), main=$('#main');
const world=createWorld(document.querySelector('#gallery-world'),id=>{location.hash=`#oeuvre/${encodeURIComponent(id)}`;});
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${({heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 4.5 4.5"/>',plus:'<path d="M12 4v16M4 12h16"/>',check:'<path d="m5 12 4 4L19 6"/>',image:'<rect x="3" y="3" width="18" height="18" rx="1"/><circle cx="8" cy="8" r="1.5"/><path d="m3 17 5-5 4 4 4-6 5 7"/>'})[name]}</svg>`;
let storageError='',works, favorites=[];
try{const stored=localStorage.getItem(KEY);works=stored?JSON.parse(stored):structuredClone(seed);if(!Array.isArray(works)||!works.every(validWork))throw Error('invalid');works=refreshDemoPresentation(refreshDemoPrices(works));const saved=JSON.parse(localStorage.getItem('edit-favorites-v1')||'[]');if(Array.isArray(saved))favorites=saved.filter(v=>typeof v==='string');}
catch{works=structuredClone(seed);storageError='Les données locales n’ont pas pu être lues. Les exemples sont affichés ; aucune donnée existante n’a été écrasée.';}
let category='Toutes',query='',status='all',toastTimer,editorDirty=false;
const published=()=>works.filter(canExhibit);
let disposeGallery=()=>{},disposeArtwork=()=>{},galleryPosition=0,galleryWorkId=null;
function notify(message){const t=$('#toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3200);}
function persist(next){try{localStorage.setItem(KEY,JSON.stringify(next));works=next;return true;}catch{notify('Sauvegarde impossible. Libérez de l’espace ou choisissez une image plus légère.');return false;}}
function navigate(hash){location.hash=hash;}
function header(){const admin=location.hash.startsWith('#atelier');$('#header').innerHTML=`<div class="wrap"><div class="site-header"><nav class="nav-left" aria-label="Navigation galerie"><a class="nav-link gallery-home" href="#">La galerie</a><a class="nav-link" href="#collection">Catalogue</a></nav><a class="brand" href="#" aria-label="PEINTURE — Accueil">PEINTURE</a><nav class="nav-right" aria-label="Navigation principale"><a class="selection-link ${location.hash==='#selection'?'filled':''}" href="#selection" aria-label="Ma sélection, ${favorites.length} œuvre${favorites.length>1?'s':''}">${icon('heart')}<span class="selection-text">Ma sélection</span><span class="selection-number">(${favorites.length})</span></a><details class="site-menu"><summary>Menu</summary><div class="site-menu-panel"><a href="#">La galerie</a><a href="#esprit">À propos</a><a href="#selection">Ma sélection</a><a href="assets/credits.html" target="_blank" rel="noopener">Crédits des visuels</a><a href="#atelier" ${admin?'aria-current="page"':''}>L’atelier</a></div></details></nav></div></div>`;}
function footer(){ $('#footer').innerHTML=''; }
function heart(w){return `<button class="heart ${favorites.includes(w.id)?'filled':''}" data-favorite="${e(w.id)}" aria-label="${favorites.includes(w.id)?'Retirer de':'Ajouter à'} ma sélection : ${e(w.title)}" aria-pressed="${favorites.includes(w.id)}">${icon('heart')}</button>`;}
function card(w){return `<article class="work-card" data-frame="${frameFor(w)}"><a href="#oeuvre/${encodeURIComponent(w.id)}" class="image-link" aria-label="Découvrir ${e(w.title)}"><img src="${e(w.image)}" alt="${e(w.title)}" loading="lazy" width="600" height="750"></a>${heart(w)}<div class="work-caption"><div><h3><a href="#oeuvre/${encodeURIComponent(w.id)}">${e(w.title)}</a></h3><p>${e(w.artist)} · ${e(w.year)}</p></div></div><div class="work-meta"><span>${e(w.medium)} · ${w.width} × ${w.height} cm</span><span>${currency(w.price)}</span></div></article>`;}
const search=(placeholder)=>`<label class="search">${icon('search')}<input id="search" type="search" placeholder="${placeholder}" aria-label="${placeholder}" value="${e(query)}"></label>`;
function galleryResults(selection=false){const filtered=filterWorks(published(),{category,query,favorites:selection?favorites:null});$('#works-grid').innerHTML=filtered.length?filtered.map(card).join(''):`<div class="empty"><h2>${selection?'Votre sélection est vide.':'Aucune œuvre pour le moment.'}</h2><p>${selection?'Enregistrez les œuvres qui retiennent votre regard.':'Essayez un autre mot ou explorez une autre technique.'}</p>${selection?'<a class="button" href="#collection">Découvrir les œuvres</a>':'<button class="button secondary" data-reset-filters>Effacer les filtres</button>'}</div>`;$('#gallery-count').textContent=`${filtered.length} œuvre${filtered.length>1?'s':''} ${selection?'dans votre sélection':'à découvrir'}`;}
function galleryControls(){return `<div class="toolbar"><div class="tabs" aria-label="Techniques">${['Toutes','Peinture','Photographie','Sculpture','Édition'].map(c=>`<button class="tab" data-category="${c}" aria-pressed="${category===c}">${c}</button>`).join('')}</div>${search('Rechercher une œuvre')}</div><div class="works-grid" id="works-grid"></div><p id="gallery-count" class="gallery-count" aria-live="polite"></p>`;}
function home(){const exhibited=published();if(galleryWorkId)galleryPosition=Math.max(0,exhibited.findIndex(work=>work.id===galleryWorkId));main.innerHTML=galleryMarkup(exhibited,heart);world.show(exhibited,null,'visit');disposeGallery=mountGallery($('#galerie'),exhibited,{favorites:()=>favorites,initialProgress:galleryPosition,onPosition:value=>{galleryPosition=value;galleryWorkId=exhibited[Math.round(value)]?.id;},world});}
function catalogue(){main.innerHTML=`<section class="world-panel catalogue-overlay" data-world-panel><div class="panel-heading"><a class="back" href="#galerie">Reprendre la visite</a><h1>Les œuvres.</h1><p>À partir de ${currency(MIN_PRICE)}</p></div>${galleryControls()}</section>`;galleryResults();bindSearch(()=>galleryResults());world.show(published(),null,'overview',$('[data-world-panel]'));}
function spirit(){main.innerHTML=`<section class="world-panel spirit-panel" data-world-panel><a class="back" href="#galerie">Reprendre la visite</a><h1>La galerie.</h1><p>Explorez les œuvres, consultez leur fiche et préparez votre demande d’acquisition.</p><a class="button" href="#galerie">Visiter la galerie</a></section>`;world.show(published(),null,'overview',$('[data-world-panel]'));}
function selection(){category='Toutes';query='';main.innerHTML=`<section class="world-panel selection-page catalogue-overlay" data-world-panel><div class="page-heading"><div><a class="back" href="#collection">Retour aux œuvres</a><h1>Votre sélection.</h1><p>Les œuvres que vous avez envie de retrouver.</p></div></div>${galleryControls()}</section>`;galleryResults(true);bindSearch(()=>galleryResults(true));world.show(published(),favorites[0],'overview',$('[data-world-panel]'));}
function bindSearch(cb){$('#search')?.addEventListener('input',event=>{query=event.target.value;cb();});}
function detail(id){const w=published().find(w=>w.id===id);if(!w){document.title='Œuvre indisponible — PEINTURE';main.innerHTML=`<div class="wrap"><div class="empty"><h1>Cette œuvre n’est plus exposée.</h1><p>Retrouvez les autres œuvres de la galerie.</p><a href="#collection" class="button">Explorer la galerie</a></div></div>`;return;}
main.innerHTML=artworkMarkup(w,favorites.includes(w.id),icon('heart'));disposeArtwork=mountArtwork(main.querySelector('.artwork-page'),w);main.querySelector('[data-inspect-work]').addEventListener('click',()=>world.inspect());galleryPosition=Math.max(0,published().findIndex(item=>item.id===id));galleryWorkId=id;world.show(published(),id,'detail',main.querySelector('.artwork-page'));document.title=`${w.title} — PEINTURE`;}
function dashboard(){main.innerHTML=`<div class="world-panel management-panel" data-world-panel><div class="page-heading"><div><h1>Votre atelier.</h1><p>Gérer les œuvres et les accrochages.</p></div><a class="button" href="#atelier/nouveau">${icon('plus')} Ajouter une œuvre</a></div><div class="catalogue-stats"><div><strong>${works.length}</strong><span>œuvre${works.length>1?'s':''} au catalogue</span></div><div><strong>${published().length}</strong><span>publiée${published().length>1?'s':''}</span></div><div><strong>${works.filter(w=>w.status==='draft').length}</strong><span>brouillon${works.filter(w=>w.status==='draft').length>1?'s':''}</span></div></div><p class="local-note">${icon('check')} Œuvres enregistrées dans ce navigateur.</p><div class="toolbar"><div class="tabs" aria-label="Statut des œuvres">${[['all','Toutes les œuvres'],['published','Publiées'],['draft','Brouillons']].map(([v,l])=>`<button class="tab" data-status="${v}" aria-pressed="${status===v}">${l}</button>`).join('')}</div>${search('Rechercher au catalogue')}</div><div class="catalogue-list" id="catalogue-list"></div></div>`;dashboardResults();bindSearch(dashboardResults);world.show(published(),galleryWorkId,'overview',$('[data-world-panel]'));}
function dashboardResults(){const filtered=filterWorks(works,{query,status});$('#catalogue-list').innerHTML=filtered.length?`<div class="list-head"><span>Œuvre</span><span>Prix</span><span>Statut</span><span style="text-align:right">Actions</span></div>${filtered.map(w=>`<article class="work-row"><div class="row-art"><img src="${e(w.image)}" alt="" width="66" height="80"><div><strong>${e(w.title)}</strong><p>${e(w.artist)} · ${w.width} × ${w.height} cm</p></div></div><span class="row-price">${currency(w.price)}</span><div class="row-status"><button class="status ${w.status==='draft'?'draft':''}" data-toggle="${e(w.id)}" aria-label="${w.status==='draft'?'Publier':'Passer en brouillon'} : ${e(w.title)}" title="${w.status==='draft'?'Publier':'Passer en brouillon'}">${w.status==='published'?(w.price<MIN_PRICE?'Prix à réévaluer':'Publiée'):'Brouillon'}</button></div><div class="row-actions"><a href="#atelier/modifier/${encodeURIComponent(w.id)}">Modifier</a><button class="danger" data-delete="${e(w.id)}" aria-label="Supprimer ${e(w.title)}">Supprimer</button></div></article>`).join('')}`:`<div class="empty"><h2>${works.length?'Aucune œuvre dans cette vue.':'Aucune œuvre pour le moment.'}</h2><p>${works.length?'Essayez une autre recherche ou un autre statut.':'Ajoutez une œuvre pour préparer son accrochage.'}</p><a class="button" href="#atelier/nouveau">Ajouter une œuvre</a></div>`;}
const field=(label,name,value='',type='text',extra='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${e(value)}" ${extra}></label>`;
function editor(id){const w=id?works.find(w=>w.id===id):null;if(id&&!w){navigate('#atelier');return;}let imageSrc=w?.image||'';let uploading=false;
main.innerHTML=`<div class="configurator"><div class="page-heading"><div><a class="back" href="#atelier">Retour au catalogue</a><h1>${w?'Modifier l’œuvre.':'Une nouvelle œuvre.'}</h1><p>Préparer l’accrochage et renseigner la fiche.</p></div></div><div class="editor-layout"><form id="work-form" class="world-panel configurator-form" data-world-panel><div class="configurator-heading"><a class="back" href="#atelier">Retour à l’atelier</a><h1>Configurer l’œuvre.</h1><p>Le visuel et le cadre prennent place directement dans la galerie.</p></div><section class="form-section"><h2>L’œuvre</h2>${field('Titre de l’œuvre','title',w?.title,'text','required maxlength="100" placeholder="Un titre, une première impression"')}${field('Artiste','artist',w?.artist,'text','required maxlength="100" placeholder="Nom de l’artiste"')}<div class="field-pair"><label class="field">Catégorie<select name="category">${['Peinture','Photographie','Sculpture','Édition'].map(c=>`<option ${w?.category===c?'selected':''}>${c}</option>`).join('')}</select></label>${field('Année','year',w?.year||new Date().getFullYear(),'number','required min="1000" max="2100" step="1"')}</div>${field('Technique','medium',w?.medium,'text','required maxlength="100" placeholder="Ex. : huile sur toile"')}<div class="field-pair">${field('Largeur (cm)','width',w?.width,'number','required min="0.1" max="100000" step="0.1" placeholder="80"')}${field('Hauteur (cm)','height',w?.height,'number','required min="0.1" max="100000" step="0.1" placeholder="100"')}</div>${field('Prix (€)','price',w?.price,'number','required min="500000" max="100000000" step="1" placeholder="500000"')}<label class="field">Quelques mots sur l’œuvre<textarea name="description" required maxlength="2000" placeholder="La matière, le geste, l’intention…">${e(w?.description||'')}</textarea></label></section><section class="form-section frame-config"><h2>L’encadrement</h2><label class="field">Cadre du tableau<select name="frame">${Object.entries(frames).map(([value,profile])=>`<option value="${value}" ${frameFor(w)===value?'selected':''}>${profile.label}</option>`).join('')}</select></label><p class="small muted">Le cadre choisi est conservé dans la fiche et dans la galerie. Utilisez « Voir le cadre de côté » pour examiner son relief.</p></section><section class="form-section"><h2>Le visuel</h2><div class="upload"><input id="upload" type="file" accept="image/jpeg,image/png,image/webp" aria-label="Importer le visuel de l’œuvre"><p>JPG, PNG ou WebP · 8 Mo maximum<br>Votre œuvre sera affichée en entier.</p></div><p class="small muted" style="margin-top:18px">Ou choisir un visuel</p><div class="sample-images">${['01','05','04'].map(n=>`<button type="button" data-sample="assets/oeuvre-${n}.jpg" aria-label="Choisir le visuel ${n}" aria-pressed="${imageSrc===`assets/oeuvre-${n}.jpg`}"><img src="assets/oeuvre-${n}.jpg" alt="" width="60" height="60"></button>`).join('')}</div></section><div class="form-actions"><button class="button" name="intent" value="published" type="submit">${w?.status==='published'?'Enregistrer les modifications':'Publier l’œuvre'}</button><button class="button secondary" name="intent" value="draft" type="submit">Enregistrer en brouillon</button></div><p id="form-error" class="error" role="alert"></p><p class="small muted" style="margin-top:20px">Enregistré dans ce navigateur.</p></form><aside class="preview-panel" aria-label="Aperçu de la fiche"><p>Aperçu de votre œuvre</p><div class="preview-stage" id="preview-stage"></div><div class="preview-caption"><h3 id="preview-title"></h3><p id="preview-artist"></p><strong id="preview-price"></strong></div></aside></div></div>`;
const form=$('#work-form'),error=$('#form-error');const frameSection=form.querySelector('.frame-config'),visualSection=frameSection.nextElementSibling;form.querySelector('.configurator-heading').after(frameSection,visualSection);const previewWork={id:w?.id||'__preview__',title:w?.title||'Votre œuvre',image:imageSrc,frame:frameFor(w)};world.show([previewWork,...published().filter(item=>item.id!==previewWork.id)],previewWork.id,'editor',form);
function preview(){const data=new FormData(form);$('#preview-stage').innerHTML=imageSrc?`<img src="${e(imageSrc)}" alt="Aperçu de votre œuvre">`:`<div class="preview-empty">${icon('image')}<p style="margin-top:14px">Votre œuvre prend place ici.<br>Importez son visuel pour commencer.</p></div>`;$('#preview-title').textContent=data.get('title')||'Le titre de votre œuvre';$('#preview-artist').textContent=data.get('artist')||'Le nom de l’artiste';$('#preview-price').textContent=Number(data.get('price'))>0?currency(Number(data.get('price'))):'Le prix de votre œuvre';world.preview(published(),{id:w?.id||'__preview__',title:data.get('title')||'Votre œuvre',artist:data.get('artist')||'',image:imageSrc,frame:data.get('frame')});}
form.addEventListener('input',()=>{editorDirty=true;preview();});
form.addEventListener('click',ev=>{const b=ev.target.closest('[data-sample]');if(!b)return;imageSrc=b.dataset.sample;editorDirty=true;form.querySelectorAll('[data-sample]').forEach(s=>s.setAttribute('aria-pressed',s===b));error.textContent='';preview();});
$('#upload').addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;error.textContent='';if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024){error.textContent='Choisissez une image JPG, PNG ou WebP de moins de 8 Mo.';ev.target.value='';return;}uploading=true;form.querySelectorAll('[type=submit]').forEach(b=>b.disabled=true);try{imageSrc=await compressImage(file);editorDirty=true;form.querySelectorAll('[data-sample]').forEach(s=>s.setAttribute('aria-pressed','false'));preview();}catch{error.textContent='Cette image ne peut pas être lue. Essayez un autre fichier.';}finally{uploading=false;form.querySelectorAll('[type=submit]').forEach(b=>b.disabled=false);}});
form.addEventListener('submit',ev=>{ev.preventDefault();if(uploading)return;error.textContent='';if(!imageSrc){error.textContent='Ajoutez un visuel avant d’enregistrer votre œuvre.';$('#upload').focus();return;}const data=new FormData(form);const next={id:w?.id||crypto.randomUUID(),title:data.get('title').trim(),artist:data.get('artist').trim(),category:data.get('category'),frame:data.get('frame'),year:Number(data.get('year')),medium:data.get('medium').trim(),width:Number(data.get('width')),height:Number(data.get('height')),price:Number(data.get('price')),description:data.get('description').trim(),image:imageSrc,status:ev.submitter?.value||'draft',demo:w?.demo||imageSrc.startsWith('assets/')};if(next.price<MIN_PRICE){error.textContent=`Le prix minimum est de ${currency(MIN_PRICE)}.`;return;}if(!validWork(next)||!next.title||!next.artist||!next.medium||!next.description){error.textContent='Renseignez les informations de l’œuvre avec du texte et des valeurs valides.';return;}if(persist(w?works.map(item=>item.id===id?next:item):[next,...works])){editorDirty=false;galleryWorkId=next.id;galleryPosition=Math.max(0,published().findIndex(item=>item.id===next.id));navigate('#atelier');notify(next.status==='published'?'Votre œuvre est publiée.':'Brouillon enregistré.');}else{error.textContent='L’enregistrement a échoué. Vos informations sont conservées à l’écran. Essayez une image plus petite.';}});preview();}
async function compressImage(file){const bitmap=await createImageBitmap(file);try{const scale=Math.min(1,1400/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement('canvas');canvas.width=Math.round(bitmap.width*scale);canvas.height=Math.round(bitmap.height*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='#faf9f6';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);return canvas.toDataURL('image/jpeg',.82);}finally{bitmap.close();}}
function toggleFavorite(id){const next=favorites.includes(id)?favorites.filter(v=>v!==id):[...favorites,id];try{localStorage.setItem('edit-favorites-v1',JSON.stringify(next));favorites=next;return true;}catch{notify('Impossible d’enregistrer la sélection dans ce navigateur.');return false;}}
document.addEventListener('click',ev=>{const link=ev.target.closest('a[href^="#"]');if(link&&editorDirty&&link.hash!==location.hash){if(!confirm('Quitter sans enregistrer vos modifications ?')){ev.preventDefault();return;}editorDirty=false;}
const target=ev.target.closest('button');if(!target)return;
if(target.hasAttribute('data-favorite')||target.hasAttribute('data-detail-favorite')){const id=target.dataset.favorite||target.dataset.detailFavorite;if(!toggleFavorite(id))return;header();if(target.hasAttribute('data-detail-favorite')){target.classList.toggle('filled',favorites.includes(id));target.setAttribute('aria-pressed',favorites.includes(id));target.querySelector('span').textContent=favorites.includes(id)?'Retirer de ma sélection':'Ajouter à ma sélection';}else if(location.hash==='#selection')galleryResults(true);else{const w=works.find(w=>w.id===id);document.querySelectorAll('[data-favorite]').forEach(button=>{if(button.dataset.favorite!==id)return;button.classList.toggle('filled',favorites.includes(id));button.setAttribute('aria-pressed',favorites.includes(id));button.setAttribute('aria-label',`${favorites.includes(id)?'Retirer de':'Ajouter à'} ma sélection : ${w?.title||''}`);});}notify(favorites.includes(id)?'Œuvre ajoutée à votre sélection.':'Œuvre retirée de votre sélection.');}
if(target.dataset.category){category=target.dataset.category;document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',b===target));galleryResults(location.hash==='#selection');}
if(target.hasAttribute('data-reset-filters')){category='Toutes';query='';$('#search').value='';document.querySelectorAll('[data-category]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.category==='Toutes'));galleryResults();}
if(target.dataset.status){status=target.dataset.status;document.querySelectorAll('[data-status]').forEach(b=>b.setAttribute('aria-pressed',b===target));dashboardResults();}
if(target.dataset.toggle){const w=works.find(w=>w.id===target.dataset.toggle);const next={...w,status:w.status==='published'?'draft':'published'};if(persist(works.map(item=>item.id===w.id?next:item))){dashboard();notify(next.status==='published'?'Œuvre publiée.':'Œuvre passée en brouillon.');}}
if(target.dataset.delete){const w=works.find(w=>w.id===target.dataset.delete);if(confirm(`Supprimer « ${w.title} » de votre catalogue ? Cette action est définitive.`)&&persist(works.filter(item=>item.id!==w.id))){dashboard();notify('Œuvre supprimée du catalogue.');}}
});
document.querySelector('.skip').addEventListener('click',event=>{event.preventDefault();main.focus({preventScroll:true});main.scrollIntoView();});
window.addEventListener('beforeunload',ev=>{if(editorDirty){ev.preventDefault();ev.returnValue='';}});
let priorHash=location.hash;
function render(){const hash=location.hash;disposeGallery();disposeGallery=()=>{};disposeArtwork();disposeArtwork=()=>{};editorDirty=false;document.body.classList.toggle('is-gallery',['','#','#galerie'].includes(hash));document.body.classList.toggle('is-artwork',hash.startsWith('#oeuvre/'));document.body.classList.toggle('is-configurator',hash==='#atelier/nouveau'||hash.startsWith('#atelier/modifier/'));document.body.classList.toggle('is-overlay',!['','#','#galerie'].includes(hash));header();footer();window.scrollTo({top:0,behavior:'instant'});if(hash==='#atelier')dashboard();else if(hash==='#atelier/nouveau')editor();else if(hash.startsWith('#atelier/modifier/'))editor(decodeURIComponent(hash.slice(18)));else if(hash.startsWith('#oeuvre/'))detail(decodeURIComponent(hash.slice(8)));else if(hash==='#selection')selection();else if(hash==='#collection')catalogue();else if(hash==='#esprit')spirit();else home();document.querySelector('.site-menu')?.removeAttribute('open');priorHash=hash;if(!hash.startsWith('#oeuvre/'))document.title=hash.startsWith('#atelier')?'L’atelier — PEINTURE':'PEINTURE — Galerie d’art';main.focus({preventScroll:true});}
window.addEventListener('hashchange',()=>{if(editorDirty){if(!confirm('Quitter sans enregistrer vos modifications ?')){history.pushState(null,'',priorHash);return;}editorDirty=false;}render();});
render();
